import { FrameworkErrorCode as Codes } from "../../utils/framework-error-codes.js";
export const FrameworkErrorCode = Codes;
const frameworkErrorCodes = new Set(Object.values(FrameworkErrorCode));
export function isFrameworkErrorCode(value) {
    return typeof value === "string" && frameworkErrorCodes.has(value);
}
export function success(value) {
    return { ok: true, value };
}
export function domainError(value) {
    return { ok: false, error: { kind: "domain", value } };
}
export function frameworkError(code, detail) {
    return { ok: false, error: { kind: "framework", code, detail } };
}
